```java
import java.io.*;
import java.util.*;

public class Main {
    static int rows, cols;
    static boolean[][] eligible;
    static int[][] matchRight;
    static boolean[][] visited;

    static boolean augment(int r, int c) {
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int k = 0; k < 4; k++) {
            int nr = r + dr[k];
            int nc = c + dc[k];

            if (nr < 0 || nr >= rows || nc < 0 || nc >= cols
                    || !eligible[nr][nc] || visited[nr][nc]) {
                continue;
            }

            visited[nr][nc] = true;
            if (matchRight[nr][nc] == -1 || augment(matchRight[nr][nc] / cols, matchRight[nr][nc] % cols)) {
                matchRight[nr][nc] = r * cols + c;
                return true;
            }
        }
        return false;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        rows = fs.nextInt();
        cols = fs.nextInt();

        int p = fs.nextInt();
        boolean[][] black = new boolean[rows][cols];
        for (int i = 0; i < p; i++) {
            int x = fs.nextInt() - 1;
            int y = fs.nextInt() - 1;
            black[x][y] = true;
        }

        eligible = new boolean[rows][cols];
        int eligibleCount = 0;
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (black[r][c]) continue;

                for (int k = 0; k < 4; k++) {
                    int nr = r + dr[k];
                    int nc = c + dc[k];
                    if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && black[nr][nc]) {
                        eligible[r][c] = true;
                        eligibleCount++;
                        break;
                    }
                }
            }
        }

        matchRight = new int[rows][cols];
        for (int[] row : matchRight) Arrays.fill(row, -1);

        int matching = 0;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (eligible[r][c] && (r + c) % 2 == 0) {
                    visited = new boolean[rows][cols];
                    if (augment(r, c)) matching++;
                }
            }
        }

        System.out.println(eligibleCount - matching);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream in) {
            this.in = in;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int ch;
            do {
                ch = read();
            } while (ch <= ' ' && ch != -1);

            int value = 0;
            while (ch > ' ') {
                value = value * 10 + ch - '0';
                ch = read();
            }
            return value;
        }
    }
}
```

